function castRogue(dt){p.bladeTimer-=dt/p.attackInterval;p.trapTimer-=dt/p.attackInterval;
if(p.bladeTimer<=0){const target=enemies.filter(e=>!e.dead).reduce((a,e)=>!a||Math.hypot(e.x-p.x,e.y-p.y)<Math.hypot(a.x-p.x,a.y-p.y)?e:a,null);const angle=target?Math.atan2(target.y-p.y,target.x-p.x):Math.atan2(p.dy,p.dx),count=1+Math.floor(p.bladeLevel/3)+(p.bladeEvolved?4:0);for(let i=0;i<count;i++){const a=angle+(i-(count-1)/2)*.22;bullets.push({blade:true,x:p.x,y:p.y,vx:Math.cos(a)*340,vy:Math.sin(a)*340,age:0,life:1.6,remaining:999,hit:new Set(),damage:p.damage*(.9+p.bladeLevel*.25)*(p.bladeEvolved?3:1)});}p.bladeTimer=1.1*(1-p.bladeHaste*.12);}
if(p.trapTimer<=0){traps.push({x:p.x,y:p.y,life:12,active:false,tick:0});p.trapTimer=p.trapEvolved?1.6:2.5;}
for(const trap of traps){trap.life-=dt;const radius=(p.trapEvolved?95:55)*(1+p.trapRange*.2);if(!trap.active&&enemies.some(e=>!e.dead&&Math.hypot(e.x-trap.x,e.y-trap.y)<radius+e.r)){trap.active=true;trap.life=p.trapEvolved?4:.35;trap.tick=0;}
if(trap.active){trap.tick-=dt;if(trap.tick<=0){for(const e of enemies)if(!e.dead&&Math.hypot(e.x-trap.x,e.y-trap.y)<radius+e.r){hurt(e,p.damage*(.7+p.trapLevel*.2)*(p.trapEvolved?3:1));e.poison=3+(p.venomVial?2:0);e.poisonDamage=p.damage*.35;e.poisonTick=0;}trap.tick=1;fx.push({x:trap.x,y:trap.y,vx:0,vy:0,life:.5,color:'#a3ef62',ring:radius});}}}traps=traps.filter(a=>a.life>0);
}
